export function portalText(language: PortalLanguage, value: string): string {
  if (language === "lv") return sprint113Text.lv[value] ?? reportWeatherFailureText.lv[value] ?? importApplyText.lv[value] ?? repeatedMarkText.lv[value] ?? groupedImportText.lv[value] ?? mappingStatusText.lv[value] ?? xlsxMappingText.lv[value] ?? sprint111Extra.lv[value] ?? sprint111Text.lv[value] ?? elementDetailText.lv[value] ?? reportLifecycleText.lv[value] ?? sprint11.lv[value] ?? printNavigationText.lv[value] ?? printViewText.lv[value] ?? reportActionText.lv[value] ?? sprint10.lv[value] ?? lv[value] ?? value;
  if (language === "ru") return sprint113Text.ru[value] ?? reportWeatherFailureText.ru[value] ?? importApplyText.ru[value] ?? repeatedMarkText.ru[value] ?? groupedImportText.ru[value] ?? mappingStatusText.ru[value] ?? xlsxMappingText.ru[value] ?? sprint111Extra.ru[value] ?? sprint111Text.ru[value] ?? elementDetailText.ru[value] ?? reportLifecycleText.ru[value] ?? sprint11.ru[value] ?? printNavigationText.ru[value] ?? printViewText.ru[value] ?? reportActionText.ru[value] ?? sprint10.ru[value] ?? ru[value] ?? value;
  return sprint113Text.en[value] ?? reportWeatherFailureText.en[value] ?? importApplyText.en[value] ?? repeatedMarkText.en[value] ?? groupedImportText.en[value] ?? mappingStatusText.en[value] ?? xlsxMappingText.en[value] ?? sprint111Extra.en[value] ?? sprint111Text.en[value] ?? elementDetailText.en[value] ?? reportLifecycleText.en[value] ?? sprint11.en[value] ?? printNavigationText.en[value] ?? printViewText.en[value] ?? reportActionText.en[value] ?? sprint10.en[value] ?? value;
}

export function normalizePortalLanguage(value: string | undefined): PortalLanguage {
  return portalLanguages.includes(value as PortalLanguage) ? value as PortalLanguage : "lv";
}
